def find_permutation(n, k):
    if k > (n * (n + 1)) // 2:
        return "NO"

    permutation = []
    left = 1
    right = n
    while left <= right:
        if k >= right - left + 1:
            k -= right - left + 1
            permutation.extend(range(right, left - 1, -1))
            break
        else:
            right -= 1

    if k > 0:
        return "NO"

    return "YES", permutation

