    q = int(input())
    results = []
    for _ in range(q):
        n, k = map(int, input().split())
        result = find_permutation(n, k)
        if result == "NO":
            results.append(result)
        else:
            results.append("YES")
            results.append(" ".join(map(str, result[1])))

    for res in results:
        print(res)

if __name__ == "__main__":
